-- Applied on the owner's yes, 6 Nov 2026. Missing spaces restored from the source: 9 PMQs archive rows from the Hansard API, 118 divisions with TextBeforeVote's line break before "The House divided:", and 72 register entries where the raw source has a tag at the join. 116 other register rows are typed that way in the source and stay as published. Every old value is matched exactly; a different row count rolls back.
BEGIN READ WRITE;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';
CREATE TEMP TABLE _pm (date date, item_order integer, old_value text NOT NULL, new_value text NOT NULL) ON COMMIT DROP;
INSERT INTO _pm VALUES
('1961-12-07'::date, 13, 'asked the Minister if, in view of President Kennedy''s successful interview reported inIzvestia,he will approach Mr. Khrushchev for similar publicity on a reciprocal basis to be given in both countries for Mr. Khrushchev and himself, respectively, so as to create better understanding as the basis for peaceful co-existence; and if he will make a statement.', 'asked the Minister if, in view of President Kennedy''s successful interview reported in Izvestia, he will approach Mr. Khrushchev for similar publicity on a reciprocal basis to be given in both countries for Mr. Khrushchev and himself, respectively, so as to create better understanding as the basis for peaceful co-existence; and if he will make a statement.'),
('1963-04-02'::date, 29, 'asked the Prime Minister if the public statements made by the Lord Privy Seal concerning the resumption of negotiations for Great Britain''s entry into the Common Market during an authorised interview published by the French newspaper,Le Monde,on 28th March represent the policy of Her Majesty''s Government.', 'asked the Prime Minister if the public statements made by the Lord Privy Seal concerning the resumption of negotiations for Great Britain''s entry into the Common Market during an authorised interview published by the French newspaper, Le Monde, on 28th March represent the policy of Her Majesty''s Government.'),
('1965-12-07'::date, 1, 'asked the Prime Minister what decision has now been reached by Her Majesty''s Government regarding the recognition of the competence of the European Commission on Human Rights to receive petitions within the terms of Article 25 of the Convention for the Protection of Human Rights and Fundamental Freedoms; and if he will now declare, pursuant to Article 46 of the Convention for the Protection of Human Rights and Fundamental Freedoms, that he recognises as compulsory,ipso factoand without special agreement, the jurisdiction of the European Court of Human Rights on all matters concerning the interpretation and application of the Convention.', 'asked the Prime Minister what decision has now been reached by Her Majesty''s Government regarding the recognition of the competence of the European Commission on Human Rights to receive petitions within the terms of Article 25 of the Convention for the Protection of Human Rights and Fundamental Freedoms; and if he will now declare, pursuant to Article 46 of the Convention for the Protection of Human Rights and Fundamental Freedoms, that he recognises as compulsory, ipso facto and without special agreement, the jurisdiction of the European Court of Human Rights on all matters concerning the interpretation and application of the Convention.'),
('1966-07-07'::date, 57, 'asked the Prime Minister if he is aware that, following the expulsion of theDaily Telegraphcorrespondent, Nigeria has now expelled Mr. Walter Schwarz ofThe Guardian; and if he will raise the issue of the freedom of the Press at the forthcoming Commonwealth Prime Ministers'' Conference.', 'asked the Prime Minister if he is aware that, following the expulsion of the Daily Telegraph correspondent, Nigeria has now expelled Mr. Walter Schwarz of The Guardian; and if he will raise the issue of the freedom of the Press at the forthcoming Commonwealth Prime Ministers'' Conference.'),
('1971-05-20'::date, 1, 'asked the Prime Minister whether he will place in the Library a copy of the public speech made on 5th May atThe Guardiandinner in London on the European Economic Community.', 'asked the Prime Minister whether he will place in the Library a copy of the public speech made on 5th May at The Guardian dinner in London on the European Economic Community.'),
('1977-07-28'::date, 7, 'asked the Prime Minister if, further to his statement,Official Report, 7th July, column 1423, that the social contract was no longer intact and his answer of 13th July to the hon. Member for Chingford (Mr. Tebbit) that it was not broken, he will clarify the present status of the social contract.', 'asked the Prime Minister if, further to his statement, Official Report, 7th July, column 1423, that the social contract was no longer intact and his answer of 13th July to the hon. Member for Chingford (Mr. Tebbit) that it was not broken, he will clarify the present status of the social contract.'),
('1980-05-08'::date, 24, 'asked the Prime Minister, whether, pursuant to the statement,Official Report,', 'asked the Prime Minister, whether, pursuant to the statement, Official Report,'),
('2013-10-23'::date, 56, 'Following the reckless handling by The Guardianof the Snowden leaks, will the Prime Minister join me in paying tribute to the women and men of our intelligence services, who have no voice but who do so much to keep this country safe?', 'Following the reckless handling by The Guardian of the Snowden leaks, will the Prime Minister join me in paying tribute to the women and men of our intelligence services, who have no voice but who do so much to keep this country safe?'),
('2015-03-25'::date, 63, 'I have here a cutting from The Pressin York on 24 April 2010, which says: “David Cameron last night dismissed claims the Tories would put up VAT if they win the election”. That was at the last election. Why should the public believe promises that he makes at the coming election?', 'I have here a cutting from The Press in York on 24 April 2010, which says: “David Cameron last night dismissed claims the Tories would put up VAT if they win the election”. That was at the last election. Why should the public believe promises that he makes at the coming election?');
DO $fix$
DECLARE n integer;
BEGIN
  UPDATE public.pmqs_archive_exchanges t SET contribution_text = f.new_value FROM _pm f WHERE t."date" = f.date AND t.item_order = f.item_order AND t.contribution_text = f.old_value;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 9 THEN RAISE EXCEPTION 'PMQs archive: expected 9 rows, touched %', n; END IF;
END
$fix$;
