DO $fix$
DECLARE n integer;
BEGIN
  UPDATE public.historic_commons_divisions t SET text_before = f.new_value FROM _div f WHERE t.external_id = f.external_id AND t.text_before = f.old_value;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 118 THEN RAISE EXCEPTION 'divisions: expected 118 rows, touched %', n; END IF;
END
$fix$;
