DO $fix$
DECLARE n integer;
BEGIN
  UPDATE public.register_archive_entries t SET text = f.new_value FROM _reg f WHERE t.entry_id = f.entry_id AND t.text = f.old_value;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 72 THEN RAISE EXCEPTION 'register: expected 72 rows, touched %', n; END IF;
END
$fix$;
COMMIT;
